        "general.autoUpdate": [.en:"Check for updates automatically", .ko:"업데이트 자동 확인", .ja:"アップデートを自動確認", .zhHans:"自动检查更新", .zhHant:"自動檢查更新", .th:"ตรวจหาอัปเดตอัตโนมัติ", .vi:"Tự động kiểm tra cập nhật", .it:"Controlla aggiornamenti automaticamente", .fr:"Rechercher les mises à jour automatiquement", .es:"Buscar actualizaciones automáticamente", .pt:"Procurar atualizações automaticamente", .hr:"Automatski provjeri ažuriranja", .de:"Automatisch nach Updates suchen", .pl:"Automatycznie sprawdzaj aktualizacje", .id:"Periksa pembaruan otomatis"],
        "general.autoUpdateDesc": [.en:"Checks once a day in the background and notifies only when a new version exists.", .ko:"하루 한 번 백그라운드로 확인하고, 새 버전이 있을 때만 알립니다.", .ja:"1日1回バックグラウンドで確認し、新バージョンがある時だけ通知します。", .zhHans:"每天在后台检查一次，仅在有新版本时通知。", .zhHant:"每天在背景檢查一次，僅在有新版本時通知。", .th:"ตรวจสอบวันละครั้งเบื้องหลัง แจ้งเตือนเฉพาะเมื่อมีเวอร์ชันใหม่", .vi:"Kiểm tra nền mỗi ngày một lần, chỉ báo khi có bản mới.", .it:"Controlla una volta al giorno in background e avvisa solo se c'è una nuova versione.", .fr:"Vérifie une fois par jour en arrière-plan et notifie uniquement si une nouvelle version existe.", .es:"Comprueba una vez al día en segundo plano y avisa solo si hay una versión nueva.", .pt:"Verifica uma vez por dia em segundo plano e avisa só quando há versão nova.", .hr:"Provjerava jednom dnevno u pozadini i javlja samo kad postoji nova verzija.", .de:"Prüft einmal täglich im Hintergrund und meldet sich nur bei einer neuen Version.", .pl:"Sprawdza raz dziennie w tle i powiadamia tylko o nowej wersji.", .id:"Memeriksa sekali sehari di latar belakang dan memberi tahu hanya jika ada versi baru."],
        "notify.updateTitle": [.en:"Update available", .ko:"업데이트 있음", .ja:"アップデートあり", .zhHans:"有可用更新", .zhHant:"有可用更新", .th:"มีอัปเดต", .vi:"Có bản cập nhật", .it:"Aggiornamento disponibile", .fr:"Mise à jour disponible", .es:"Actualización disponible", .pt:"Atualização disponível", .hr:"Dostupno ažuriranje", .de:"Update verfügbar", .pl:"Dostępna aktualizacja", .id:"Pembaruan tersedia"],
        "notify.updateBodyFmt": [.en:"DevSweep %@ is available. Open Settings → About to install.", .ko:"DevSweep %@ 가 나왔어요. 설정 → 정보에서 설치할 수 있어요.", .ja:"DevSweep %@ が利用可能です。設定 → 情報からインストールできます。", .zhHans:"DevSweep %@ 已发布。可在设置 → 关于中安装。", .zhHant:"DevSweep %@ 已發布。可在設定 → 關於中安裝。", .th:"DevSweep %@ พร้อมใช้งาน ติดตั้งได้ที่ การตั้งค่า → เกี่ยวกับ", .vi:"Đã có DevSweep %@. Cài trong Cài đặt → Giới thiệu.", .it:"DevSweep %@ è disponibile. Installa da Impostazioni → Info.", .fr:"DevSweep %@ est disponible. Installez depuis Réglages → À propos.", .es:"DevSweep %@ está disponible. Instálalo en Ajustes → Información.", .pt:"DevSweep %@ disponível. Instale em Definições → Sobre.", .hr:"DevSweep %@ je dostupan. Instalirajte u Postavke → Informacije.", .de:"DevSweep %@ ist verfügbar. Installation über Einstellungen → Info.", .pl:"DevSweep %@ jest dostępny. Zainstaluj w Ustawienia → Informacje.", .id:"DevSweep %@ tersedia. Pasang di Pengaturan → Tentang."],
