        "general.autoScan": [.en:"Auto-scan on launch", .ko:"앱 시작 시 자동 스캔", .ja:"起動時に自動スキャン", .zhHans:"启动时自动扫描", .zhHant:"啟動時自動掃描", .th:"สแกนอัตโนมัติเมื่อเปิด", .vi:"Tự quét khi mở", .it:"Scansione automatica all’avvio", .fr:"Analyse auto au lancement", .es:"Escaneo automático al abrir", .pt:"Análise automática ao abrir", .hr:"Automatsko skeniranje pri pokretanju", .de:"Beim Start automatisch scannen", .pl:"Automatyczne skanowanie przy uruchomieniu", .id:"Scan otomatis saat dibuka"],
        "general.autoScanDesc": [.en:"If off, press ‘Rescan’ manually.", .ko:"끄면 직접 ‘다시 스캔’을 눌러야 합니다.", .ja:"オフの場合は手動で「再スキャン」を押してください。", .zhHans:"关闭后需手动点击’重新扫描’。", .zhHant:"關閉後需手動點選「重新掃描」。", .th:"หากปิด ต้องกด ‘สแกนใหม่’ เอง", .vi:"Nếu tắt, hãy nhấn ‘Quét lại’ thủ công.", .it:"Se disattivato, premi ‘Riesegui scansione’.", .fr:"Si désactivé, appuyez sur ‘Réanalyser’.", .es:"Si está apagado, pulsa ‘Reescanear’.", .pt:"Se desligado, prima ‘Reanalisar’.", .hr:"Ako je isključeno, ručno pritisnite ‘Ponovno skeniraj’.", .de:"Falls aus, ‘Erneut scannen’ manuell drücken.", .pl:"Jeśli wyłączone, naciśnij ręcznie ‘Skanuj ponownie’.", .id:"Jika mati, tekan ‘Pindai ulang’ secara manual."],
        "general.selectHeavy": [.en:"Also select HEAVY categories", .ko:"HEAVY 카테고리도 기본 선택", .ja:"HEAVY カテゴリも既定で選択", .zhHans:"默认也选中 HEAVY 类别", .zhHant:"預設也選取 HEAVY 類別", .th:"เลือกหมวด HEAVY ด้วย", .vi:"Cũng chọn các mục HEAVY", .it:"Seleziona anche le categorie HEAVY", .fr:"Sélectionner aussi les catégories HEAVY", .es:"Seleccionar también categorías HEAVY", .pt:"Selecionar também categorias HEAVY", .hr:"Također odaberi HEAVY kategorije", .de:"Auch HEAVY-Kategorien auswählen", .pl:"Zaznacz też kategorie HEAVY", .id:"Juga pilih kategori HEAVY"],
        "general.selectHeavyDesc": [.en:"Auto-checks costly-to-redownload items (e.g. playwright) after scan.", .ko:"재다운로드 비용이 큰 항목(playwright 등)을 스캔 후 자동 체크합니다.", .ja:"再ダウンロードコストの大きい項目(playwright など)をスキャン後に自動チェックします。", .zhHans:"扫描后自动勾选重新下载成本高的项目(如 playwright)。", .zhHant:"掃描後自動勾選重新下載成本高的項目(如 playwright)。", .th:"เลือกอัตโนมัติสำหรับรายการที่ดาวน์โหลดใหม่แพง (เช่น playwright) หลังสแกน", .vi:"Tự chọn các mục tốn kém khi tải lại (vd: playwright) sau khi quét.", .it:"Seleziona automaticamente gli elementi costosi da riscaricare (es. playwright) dopo la scansione.", .fr:"Coche automatiquement les éléments coûteux à retélécharger (ex. playwright) après l’analyse.", .es:"Marca automáticamente los elementos costosos de redescargar (p. ej. playwright) tras escanear.", .pt:"Marca automaticamente itens caros de rebaixar (ex. playwright) após a análise.", .hr:"Nakon skeniranja automatski označi stavke skupe za ponovno preuzimanje (npr. playwright).", .de:"Markiert nach dem Scan automatisch teure Elemente zum Neu-Herunterladen (z.B. playwright).", .pl:"Automatycznie zaznacza po skanie elementy kosztowne w ponownym pobieraniu (np. playwright).", .id:"Otomatis mencentang item mahal untuk diunduh ulang (mis. playwright) setelah scan."],
        "general.notify": [.en:"Notify when done", .ko:"정리 완료 알림", .ja:"完了時に通知", .zhHans:"完成时通知", .zhHant:"完成時通知", .th:"แจ้งเตือนเมื่อเสร็จ", .vi:"Thông báo khi xong", .it:"Notifica al termine", .fr:"Notifier à la fin", .es:"Notificar al terminar", .pt:"Notificar ao concluir", .hr:"Obavijesti po završetku", .de:"Benachrichtigung nach Abschluss", .pl:"Powiadom po zakończeniu", .id:"Beritahu saat selesai"],
        "general.notifyDesc": [.en:"Send a system notification after cleanup.", .ko:"정리가 끝나면 시스템 알림을 보냅니다.", .ja:"整理後にシステム通知を送ります。", .zhHans:"清理后发送系统通知。", .zhHant:"清理後傳送系統通知。", .th:"ส่งการแจ้งเตือนระบบหลังล้างเสร็จ", .vi:"Gửi thông báo hệ thống sau khi dọn.", .it:"Invia una notifica di sistema dopo la pulizia.", .fr:"Envoyer une notification système après le nettoyage.", .es:"Enviar una notificación del sistema tras la limpieza.", .pt:"Enviar uma notificação do sistema após a limpeza.", .hr:"Pošalji sistemsku obavijest nakon čišćenja.", .de:"Nach der Bereinigung eine Systembenachrichtigung senden.", .pl:"Wyślij powiadomienie systemowe po czyszczeniu.", .id:"Kirim notifikasi sistem setelah pembersihan."],

