        // ── 설정: 보호 목록 ──
        "protect.sub": [.en:"Categories turned on here are permanently excluded from cleanup — their cache is kept and devsweep won't touch it.", .ko:"켜둔 카테고리는 정리에서 영구 제외됩니다 — 캐시가 보존되고 devsweep이 건드리지 않습니다.", .ja:"オンにしたカテゴリは整理から永久に除外されます — キャッシュは保持され、devsweep は触れません。", .zhHans:"开启的类别将永久排除在清理之外——缓存会保留,devsweep 不会触碰。", .zhHant:"開啟的類別將永久排除在清理之外——快取會保留,devsweep 不會觸碰。", .th:"หมวดที่เปิดไว้จะถูกยกเว้นจากการล้างถาวร — แคชจะถูกเก็บไว้และ devsweep จะไม่แตะต้อง", .vi:"Các mục bật ở đây sẽ bị loại trừ vĩnh viễn khỏi việc dọn — bộ nhớ đệm được giữ và devsweep không động tới.", .it:"Le categorie attivate qui sono escluse in modo permanente dalla pulizia — la cache viene mantenuta e devsweep non la tocca.", .fr:"Les catégories activées ici sont définitivement exclues du nettoyage — leur cache est conservé et devsweep n'y touche pas.", .es:"Las categorías activadas aquí se excluyen permanentemente de la limpieza — su caché se conserva y devsweep no la toca.", .pt:"As categorias ativadas aqui ficam permanentemente excluídas da limpeza — a cache é mantida e o devsweep não lhe toca.", .hr:"Ovdje uključene kategorije trajno su isključene iz čišćenja — predmemorija se zadržava i devsweep je ne dira.", .de:"Hier aktivierte Kategorien werden dauerhaft von der Bereinigung ausgeschlossen — ihr Cache bleibt erhalten und devsweep lässt ihn unangetastet.", .pl:"Włączone tutaj kategorie są na stałe wykluczone z czyszczenia — ich cache jest zachowany i devsweep go nie tknie.", .id:"Kategori yang diaktifkan di sini dikecualikan secara permanen dari pembersihan — cache-nya tetap disimpan dan devsweep tidak akan menyentuhnya."],
        "protect.countFmt": [.en:"%d protected", .ko:"보호됨 %d개", .ja:"保護中 %d個", .zhHans:"已保护 %d 项", .zhHant:"已保護 %d 項", .th:"ป้องกัน %d รายการ", .vi:"%d được bảo vệ", .it:"%d protetti", .fr:"%d protégés", .es:"%d protegidos", .pt:"%d protegidos", .hr:"%d zaštićeno", .de:"%d geschützt", .pl:"%d chronione", .id:"%d dilindungi"],
        "protect.on": [.en:"Protect (exclude from cleanup)", .ko:"보호 (정리에서 제외)", .ja:"保護(整理から除外)", .zhHans:"保护(排除清理)", .zhHant:"保護(排除清理)", .th:"ป้องกัน (ยกเว้นการล้าง)", .vi:"Bảo vệ (loại khỏi dọn)", .it:"Proteggi (escludi dalla pulizia)", .fr:"Protéger (exclure du nettoyage)", .es:"Proteger (excluir de limpieza)", .pt:"Proteger (excluir da limpeza)", .hr:"Zaštiti (isključi iz čišćenja)", .de:"Schützen (von Bereinigung ausschließen)", .pl:"Chroń (wyklucz z czyszczenia)", .id:"Lindungi (kecualikan dari pembersihan)"],
        "protect.off": [.en:"Unprotect", .ko:"보호 해제", .ja:"保護を解除", .zhHans:"取消保护", .zhHant:"取消保護", .th:"ยกเลิกการป้องกัน", .vi:"Bỏ bảo vệ", .it:"Rimuovi protezione", .fr:"Retirer la protection", .es:"Quitar protección", .pt:"Remover proteção", .hr:"Ukloni zaštitu", .de:"Schutz aufheben", .pl:"Usuń ochronę", .id:"Hapus perlindungan"],

