        "age.daysFmt": [.en:"%d days or older", .ko:"%d일 이상", .ja:"%d日以上", .zhHans:"%d 天以上", .zhHant:"%d 天以上", .th:"%d วันขึ้นไป", .vi:"Từ %d ngày", .it:"%d giorni o più", .fr:"%d jours ou plus", .es:"%d días o más", .pt:"%d dias ou mais", .hr:"%d dana ili više", .de:"%d Tage oder älter", .pl:"%d dni lub starsze", .id:"%d hari atau lebih"],
        "age.note": [.en:"Only files older than the selected period are cleaned. Categories without a path (docker, simulators, rustup) are excluded.", .ko:"선택한 기간보다 오래된 파일만 정리됩니다. 경로가 없는 항목(docker·시뮬레이터·rustup)은 제외됩니다.", .ja:"選択した期間より古いファイルのみ整理されます。パスのない項目(docker・シミュレータ・rustup)は除外されます。", .zhHans:"仅清理早于所选时间的文件。无路径的项目(docker、模拟器、rustup)将被排除。", .zhHant:"僅清理早於所選時間的檔案。無路徑的項目(docker、模擬器、rustup)將被排除。", .th:"ล้างเฉพาะไฟล์ที่เก่ากว่าช่วงที่เลือก รายการที่ไม่มีพาธ (docker, ซิมูเลเตอร์, rustup) จะถูกยกเว้น", .vi:"Chỉ dọn các tệp cũ hơn khoảng thời gian đã chọn. Các mục không có đường dẫn (docker, trình mô phỏng, rustup) bị loại trừ.", .it:"Vengono puliti solo i file più vecchi del periodo selezionato. Le categorie senza percorso (docker, simulatori, rustup) sono escluse.", .fr:"Seuls les fichiers plus anciens que la période choisie sont nettoyés. Les catégories sans chemin (docker, simulateurs, rustup) sont exclues.", .es:"Solo se limpian los archivos más antiguos que el período seleccionado. Se excluyen las categorías sin ruta (docker, simuladores, rustup).", .pt:"Apenas os ficheiros mais antigos que o período selecionado são limpos. Categorias sem caminho (docker, simuladores, rustup) são excluídas.", .hr:"Čiste se samo datoteke starije od odabranog razdoblja. Kategorije bez putanje (docker, simulatori, rustup) su isključene.", .de:"Nur Dateien, die älter als der gewählte Zeitraum sind, werden bereinigt. Kategorien ohne Pfad (docker, Simulatoren, rustup) sind ausgeschlossen.", .pl:"Czyszczone są tylko pliki starsze niż wybrany okres. Kategorie bez ścieżki (docker, symulatory, rustup) są wykluczone.", .id:"Hanya file yang lebih tua dari periode yang dipilih yang dibersihkan. Kategori tanpa jalur (docker, simulator, rustup) dikecualikan."],
        "age.badgeFmt": [.en:"%d days+ only", .ko:"%d일+ 만", .ja:"%d日+ のみ", .zhHans:"仅 %d 天+", .zhHant:"僅 %d 天+", .th:"เฉพาะ %d วัน+", .vi:"Chỉ %d ngày+", .it:"Solo %d giorni+", .fr:"%d jours+ uniq.", .es:"Solo %d días+", .pt:"Só %d dias+", .hr:"Samo %d dana+", .de:"Nur %d Tage+", .pl:"Tylko %d dni+", .id:"Hanya %d hari+"],

